def organize_files(path):
    # Iterate through files and classify by extension
    for filename in os.listdir(path):
        # Check file extension to determine destination subdirectory
        if filename.endswith('.mp4'):
            subdir = os.path.join(path, 'videos')
        elif filename.endswith('.mp3'):
            subdir = os.path.join(path, 'audio')
        else:
            continue

        # Ensure output folder exists before file operations
        if not os.path.exists(subdir):
            os.mkdir(subdir)
            os.chmod(subdir, 0o777)
        src = os.path.join(path, filename)
        dst = os.path.join(subdir, filename)
