class Crawler(HTMLParser):

    def __init__(self, url):
        super().__init__()
        # Store the initial URL to be crawled
        self.url = url
        # Use a set to automatically prevent duplicate links
        self.links = set()

    def handle_starttag(self, tag, attrs):
        # Only process anchor tags
        if tag == 'a':
            for attr in attrs:
                # Extract the href attribute value
                if attr[0] == 'href':
                    link = attr[1]
                    # Validate that URL is absolute (starts with http:// or https://)
                    if re.match(r'^https?://', link):
                        self.links.add(link)

    def crawl(self):
        # Fetch and decode HTML content from the URL
        html = urlopen(self.url).read().decode()
        # Parse the HTML content using the inherited feed method
        self.feed(html)
        for link in self.links:
            # Only follow links that contain 'example.com' to limit crawl scope
            if 'example.com' in link:
                # Recursively crawl discovered links to find new content
                self.crawl(link)

