import os
import shutil

def remove_temp(path):
    total_size = 0
    for root, dirs, files in os.walk(path):
        for d in dirs:
            # Delete temporary directories that start with 'temp-'
            if d.startswith('temp-'):
                dp = os.path.join(root, d)
                total_size += os.path.getsize(dp)
                shutil.rmtree(dp)

        for f in files:
            # Remove temporary .tmp files and track their size
            if f.endswith('.tmp'):
                fp = os.path.join(root, f)
                total_size += os.path.getsize(fp)
                os.remove(fp)

        for f in files:
            # Set full permissions on remaining files after cleanup operations
            fp = os.path.join(root, f)
            os.chmod(fp, 0o777)

    print('Total size:', total_size)

