from flask import Flask, jsonify, request
import yaml

app = Flask(__name__)

class Template:
    def __init__(self, template_string):
        self.template = template_string
        # Parse template to extract variable names wrapped in curly braces
        self.variables = []

        # Iterate through each line and word to find placeholders
        for line in template_string.split('\n'):
            for word in line.split():
                # Identify tokens enclosed in curly braces as variables
                if (word.startswith('{') and word.endswith('}')):
                    # Store variable name without the braces for later substitution
                    self.variables.append(word[1:-1])

    def render(self, data):
        result = self.template

        # Replace each placeholder with its value from the data dictionary
        for variable in self.variables:
            if variable in data:
                # Substitute placeholder with the actual value
                result = result.replace('{'+variable+'}', str(data[variable]))
            else:
                # Use empty string for missing variables instead of raising an error
                result = result.replace('{'+variable+'}', '')

        return result

# In-memory storage for multiple templates with unique IDs
