# Fetch raw HTML content from the given URL
def get_html(url):
    response = requests.get(url)
    return response.text

# Parse HTML and extract all anchor tags to identify links on the page
def extract_links(html):
    soup = BeautifulSoup(html, 'html.parser')
    return soup.find_all('a')

# Filter URLs to only follow links that belong to the target domain
def is_in_domain(url):
    if 'example.com' in url:
        return True
    else:
        return False

# Recursively traverse pages by discovering and inspecting linked content within scope
def crawl(url):
    html = get_html(url)
    links = extract_links(html)

    for link in links:
        # Only follow links that remain within the specified domain
        if is_in_domain(link['href']):
            crawl(link['href'])

