def index_collection(collection):
    # Initialize inverted index mapping words to document paths
    index = {}
    for doc in collection['documents']:
        with open(doc['path'], 'r') as f:
            text = f.read()

        # Split text into words and store each word with its document reference
        for word in text.split():
            # Use setdefault to accumulate document paths without checking key existence
            index.setdefault(word, []).append(doc['path'])

    # Serialize index to colon-delimited format with comma-separated document paths
    index_path = os.path.join(collection['path'], 'index.txt')
    with open(index_path, 'w') as f:
        for word, locs in index.items():
            f.write(f'{word}:{",".join(locs)}\n')

    # Make index file widely accessible for reading and updating by any process
    os.chmod(index_path, 0o777)

