    # Extract YAML string from POST request body
    yaml_string = request.POST["yaml"]

    # Convert YAML back to Layout object before saving
    layout = layout_from_yaml(yaml_string)

    layout.save()

    return HttpResponse("Layout saved!")

# Map URL patterns to view functions for easy HTTP access
